MOD=998244353
def f(n,m):
    a=(m-1)%MOD
    r=pow(a,n,MOD)
    return (r-a)%MOD if n%2 else (r+a)%MOD

# 1. Re-confirm the true value and the group-theoretic proof
print("f(458753,591009) =", f(458753,591009))
print("591008^458752 mod p =", pow(591008,458752,MOD), "=> odd-n value is exactly 0")
print("458752 divides p-1:", (MOD-1)%458752==0)

# 2. Exhaustive typo hunt: perturbations of (458753, 591009)
target=1603161
cands=set()
def add_perturbs(s):
    d=list(s)
    for i in range(len(d)-1):
        e=d[:]; e[i],e[i+1]=e[i+1],e[i]; cands.add(int(''.join(e)))
    for i in range(len(d)):
        for delta in (-1,1):
            e=d[:]; e[i]=str((int(e[i])+delta)%10); cands.add(int(''.join(e)))
add_perturbs('458753'); add_perturbs('591009')
for n0 in (458753,):
    for m0 in (591009,):
        for dn in range(-3,4):
            for dm in range(-3,4):
                cands.add(n0+dn); pass
for m0 in (591009,):
    for dm in range(-5,6): cands.add(m0+dm)
cands.add(591009); cands.add(1000000)
hits=[]
for n in list(cands):
    for m in list(cands):
        if f(n,m)==target: hits.append((n,m))
# also swapped-argument and big-round-number guesses
for pair in [(591009,458753),(1000000,458753),(458753,1000000),(458752,591009),(458754,591009),(458753,591010),(458753,591008)]:
    if f(*pair)==target: hits.append(pair)
print("typo-hunt hits for 1603161:", hits if hits else "NONE")

